//! FerrisRBE: a Remote Execution API server for Bazel.
//!
//! The crate provides the REAPI services (CAS, Action Cache, ByteStream,
//! Execution, Remote Asset), the Build Event Service with its web UI and
//! MCP endpoint, the pull-through download proxy, and the worker runtime.

pub mod bes;
pub mod cache;
pub mod cas;
pub mod execution;
pub mod grpc_credentials;
pub mod mcp;
pub mod metrics;
pub mod proxy;
pub mod readiness;
pub mod server;
pub mod types;
pub mod worker;

/// Protobuf and gRPC types generated by `prost`/`tonic` at build time.
///
/// The module tree mirrors the protobuf package tree, because generated code
/// refers to other packages through relative `super::` paths; Bazel's own
/// packages (`failure_details`, `command_line`, `options`, `blaze`, …) are
/// siblings of `build_event_stream` for that reason.
#[allow(clippy::all)]
pub mod proto {
    /// `build.bazel.*`: Bazel's event stream and the REAPI.
    pub mod build {
        pub mod bazel {
            pub mod build_event_stream {
                include!(concat!(env!("OUT_DIR"), "/build_event_stream.rs"));
            }
            pub mod failure_details {
                include!(concat!(env!("OUT_DIR"), "/failure_details.rs"));
            }
            pub mod command_line {
                include!(concat!(env!("OUT_DIR"), "/command_line.rs"));
            }
            pub mod options {
                include!(concat!(env!("OUT_DIR"), "/options.rs"));
            }
            pub mod blaze {
                include!(concat!(env!("OUT_DIR"), "/blaze.rs"));
                pub mod invocation_policy {
                    include!(concat!(env!("OUT_DIR"), "/blaze.invocation_policy.rs"));
                }
                pub mod strategy_policy {
                    include!(concat!(env!("OUT_DIR"), "/blaze.strategy_policy.rs"));
                }
            }
            pub mod devtools {
                pub mod build {
                    pub mod lib {
                        pub mod packages {
                            pub mod metrics {
                                include!(concat!(
                                    env!("OUT_DIR"),
                                    "/devtools.build.lib.packages.metrics.rs"
                                ));
                            }
                        }
                    }
                }
            }

            pub mod semver {
                include!(concat!(env!("OUT_DIR"), "/build.bazel.semver.rs"));
            }

            pub mod remote {
                pub mod execution {
                    pub mod v2 {
                        include!(concat!(
                            env!("OUT_DIR"),
                            "/build.bazel.remote.execution.v2.rs"
                        ));
                    }
                }

                pub mod asset {
                    pub mod v1 {
                        include!(concat!(env!("OUT_DIR"), "/build.bazel.remote.asset.v1.rs"));
                    }
                }
            }
        }
    }

    /// `google.*`: ByteStream, the Build Event Service, long-running
    /// operations and RPC status.
    pub mod google {
        pub mod bytestream {
            include!(concat!(env!("OUT_DIR"), "/google.bytestream.rs"));
        }
        pub mod devtools {
            pub mod build {
                pub mod v1 {
                    include!(concat!(env!("OUT_DIR"), "/google.devtools.build.v1.rs"));
                }
            }
        }
        pub mod longrunning {
            include!(concat!(env!("OUT_DIR"), "/google.longrunning.rs"));
        }
        pub mod rpc {
            include!(concat!(env!("OUT_DIR"), "/google.rpc.rs"));
        }
    }

    /// FerrisRBE's own worker protocol.
    pub mod ferris {
        pub mod rbe {
            pub mod worker {
                tonic::include_proto!("ferris.rbe.worker");
            }
        }
    }

    /// `tools.protos`: Bazel's execution log (`SpawnExec`).
    pub mod tools {
        pub mod protos {
            include!(concat!(env!("OUT_DIR"), "/tools.protos.rs"));
        }
    }
}
